return {["modules/era/lua/items/flask_of_deodorizer.lua"]={["Path"]="modules/era/lua/items/flask_of_deodorizer.lua",["SHA256"]="7467bfa85a7d2facb0fbe48a7bc77516fea8f65cac1182bbf42cf48263785ec2",["Text"]="-----------------------------------\n-- Restores the random Deodorize duration (1 minute 30 seconds to 6 minutes).\n-- Changed December 7th, 2010 : https://www.playonline.com/pcd/verup/ff11/detail/6024/detail.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_deodorizer_duration', xi.pre(xi.expansion.ABYSSEA))\n\nm:addOverride('xi.items.flask_of_deodorizer.onItemUse', function(target, user)\n    if not target:hasStatusEffect(xi.effect.DEODORIZE) then\n        target:addStatusEffect(xi.effect.DEODORIZE, { power = 1, duration = math.random(90, 360), origin = user, tick = 10 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend)\n"},["modules/era/lua/items/pinch_of_prism_powder.lua"]={["Path"]="modules/era/lua/items/pinch_of_prism_powder.lua",["SHA256"]="1738618213715ceb7294b51f4c56187f62a24ff9bb201bc851aaa15382642cdd",["Text"]="-----------------------------------\n-- Restores the random Invisible duration (1 minute 30 seconds to 6 minutes).\n-- Changed December 7th, 2010 : https://www.playonline.com/pcd/verup/ff11/detail/6024/detail.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_prism_powder_duration', xi.pre(xi.expansion.ABYSSEA))\n\nm:addOverride('xi.items.pinch_of_prism_powder.onItemUse', function(target, user)\n    if target:hasStatusEffect(xi.effect.INVISIBLE) then\n        target:delStatusEffect(xi.effect.INVISIBLE)\n    end\n\n    target:addStatusEffect(xi.effect.INVISIBLE, { power = 1, duration = math.floor(math.random(90, 360) * xi.settings.main.SNEAK_INVIS_DURATION_MULTIPLIER), origin = user, tick = 10 })\nend)\n"},["modules/era/lua/items/pinch_of_rainbow_powder.lua"]={["Path"]="modules/era/lua/items/pinch_of_rainbow_powder.lua",["SHA256"]="b05eb644aa197215670d96348fd04c0043a85d503828880c17ca57b7a6ceceb7",["Text"]="-----------------------------------\n-- Restores the fixed 3 minute Invisible duration.\n-- Changed December 7th, 2010 : https://www.playonline.com/pcd/verup/ff11/detail/6024/detail.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_rainbow_powder_duration', xi.pre(xi.expansion.ABYSSEA))\n\nm:addOverride('xi.items.pinch_of_rainbow_powder.onItemUse', function(target, user)\n    if target:hasStatusEffect(xi.effect.INVISIBLE) then\n        target:delStatusEffect(xi.effect.INVISIBLE)\n    end\n\n    target:addStatusEffect(xi.effect.INVISIBLE, { power = 1, duration = math.floor(180 * xi.settings.main.SNEAK_INVIS_DURATION_MULTIPLIER), origin = user, tick = 10 })\nend)\n"},["modules/era/lua/items/pot_of_silent_oil.lua"]={["Path"]="modules/era/lua/items/pot_of_silent_oil.lua",["SHA256"]="01c7b9da919ac6d703a5a6d9499cce5d8f048bd4088164b4e631fa8fcd62896a",["Text"]="-----------------------------------\n-- Restores the random Sneak duration (1 minute 30 seconds to 6 minutes).\n-- Changed December 7th, 2010 : https://www.playonline.com/pcd/verup/ff11/detail/6024/detail.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_silent_oil_duration', xi.pre(xi.expansion.ABYSSEA))\n\nm:addOverride('xi.items.pot_of_silent_oil.onItemUse', function(target, user)\n    if not target:hasStatusEffect(xi.effect.SNEAK) then\n        target:addStatusEffect(xi.effect.SNEAK, { power = 1, duration = math.floor(math.random(90, 360) * xi.settings.main.SNEAK_INVIS_DURATION_MULTIPLIER), origin = user, tick = 10 })\n    end\nend)\n"},["modules/phoenix/dynamis/lua/dynamis_items.lua"]={["Path"]="modules/phoenix/dynamis/lua/dynamis_items.lua",["SHA256"]="d733596c2f09841e5f21505a73374ed8942133ceaaf8817ca2221704acbb6e7b",["Text"]="-----------------------------------\n-- Dynasmis Item Overrides\n-----------------------------------\n-- This is only used for DYNAMIS only items.\n-----------------------------------\nlocal m = Module:new('dynamis_items')\n\n-----------------------------------\n-- perpetual_hourglass\n-----------------------------------\nm:addOverride('xi.items.perpetual_hourglass.onItemCheck', function(target, item, param, caster)\n    return xi.dynamis.onGlassCheck(target, item)\nend)\n\nm:addOverride('xi.items.perpetual_hourglass.onItemUse', function(target, user, item, action)\n    xi.dynamis.onGlassUse(target, item)\nend)\n"},["modules/phoenix/lua/items/era_items.lua"]={["Path"]="modules/phoenix/lua/items/era_items.lua",["SHA256"]="fd1f543318f1d05677dd83f51e93297f8760b5d08b9b7311fb4a03fb4f580432",["Text"]="-----------------------------------\n-- Era Items Module\n-- Adjusts item availability and properties to match era-appropriate values\n-- These are only meant to be here for items that require a DAT edit to change\n-----------------------------------\nlocal m = Module:new('era_items')\n\n-- Chariot Band\n-- Bonus: +75%\n-- Duration: 720 min -> 90 min\n-- Max bonus: 10000 exp -> 500 exp\nm:addOverride('xi.items.chariot_band.onItemUse', function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 75\n    local duration  = 5400 -- 90 minutes in seconds\n    local subpower  = 500  -- Max bonus of 500 exp\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend)\n\n-- Empress Band\n-- Bonus: +50%\n-- Duration: 720 min -> 180 min\n-- Max bonus: 10000 exp -> 1000 exp\nm:addOverride('xi.items.empress_band.onItemUse', function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 50\n    local duration  = 10800 -- 180 minutes in seconds\n    local subpower  = 1000  -- Max bonus of 1000 exp\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend)\n\n-- Emperor Band\n-- Bonus: +50%\n-- Duration: 720 min -> 210 min\n-- Max bonus: 30000 exp -> 2000 exp\nm:addOverride('xi.items.emperor_band.onItemUse', function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 50\n    local duration  = 12600 -- 210 minutes in seconds\n    local subpower  = 2000  -- Max bonus of 2000 exp\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend)\n\n-- Anniversary Ring\n-- Bonus: +100%\n-- Duration: 720 min\n-- Max bonus: 10000 exp -> 3000 exp\nm:addOverride('xi.items.anniversary_ring.onItemUse', function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 100\n    local duration  = 43200 -- 720 minutes in seconds\n    local subpower  = 3000  -- Max bonus of 3000 exp\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend)\n"},["scripts/items/a_loutrance.lua"]={["Path"]="scripts/items/a_loutrance.lua",["SHA256"]="16a7a66ea8c9494a815adb253f22bf60d09eff897afe8ce56a624969865ef40f",["Text"]="-----------------------------------\n-- ID: 18041\n-- Item: A l'Outrance\n-- Additional effect: darkness damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local ecosystem = target:isMob() and target:getEcosystem() or xi.ecosystem.UNCLASSIFIED\n\n    if ecosystem ~= xi.ecosystem.BEAST then\n        return 0, 0, 0\n    end\n\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local power  = 11 + utils.clamp(math.floor(dStat * 0.6482), 0, 35) -- 0-35 over 54 dINT, linearly interpolated.\n    local pTable =\n    {\n        chance         = 100,\n        basePower      = math.randomInt(power, power + 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.DARK,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/abrasion_bolt_quiver.lua"]={["Path"]="scripts/items/abrasion_bolt_quiver.lua",["SHA256"]="a7300fc078ec03da0538cf2db2bea2049c813ef3e5d6426a81c021ea8fbbb7ae",["Text"]="-----------------------------------\n-- ID: 6278\n-- Item: Abr. Bolt Quiver\n-- When used, you will obtain one stack of Abrasion Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ABRASION_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/absorbing_shield.lua"]={["Path"]="scripts/items/absorbing_shield.lua",["SHA256"]="049976a6f3b7c59254112b0d3f747d31b806ed6dd2625154c850f329aededa1b",["Text"]="-----------------------------------\n-- ID: 12408\n-- Item: Absorbing Shield\n-- Item Effect: Transfers one random effect from the target to its user.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local numEffectsTransferred = 0\n    local availableEffects = {}\n\n    -- Get all effects from target and filter by flags\n    local allEffects = target:getStatusEffects()\n    for _, effect in pairs(allEffects) do\n        local effectId = effect:getEffectType()\n        local flags = effect:getEffectFlags()\n\n        -- Check if effect has DISPELABLE, WALTZABLE, or ERASABLE flags\n        if bit.band(flags, bit.bor(xi.effectFlag.DISPELABLE, xi.effectFlag.WALTZABLE, xi.effectFlag.ERASABLE)) ~= 0 then\n            table.insert(availableEffects, effectId)\n        end\n    end\n\n    -- Add petrification if present\n    if target:hasStatusEffect(xi.effect.PETRIFICATION) then\n        table.insert(availableEffects, xi.effect.PETRIFICATION)\n    end\n\n    -- Transfer only 1 random effect\n    if #availableEffects > 0 then\n        -- Shuffle and pick the first one\n        availableEffects = utils.shuffle(availableEffects)\n        local effectId = availableEffects[1]\n        local effect = target:getStatusEffect(effectId)\n\n        if effect then\n            user:copyStatusEffect(effect)\n            target:delStatusEffect(effectId)\n            numEffectsTransferred = 1\n        end\n    end\n\n    if numEffectsTransferred > 0 then\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/achiyalabopa_bolt_quiver.lua"]={["Path"]="scripts/items/achiyalabopa_bolt_quiver.lua",["SHA256"]="91df0c92296d304402a6ea264de8b58da22bd173cc3f8b3921ad852b0229d390",["Text"]="-----------------------------------\n-- ID: 6203\n-- Item: Al. Bolt Quiver\n-- When used, you will obtain one stack of Achiyalabopa Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ACHIYALABOPA_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/achiyalabopa_bullet_pouch.lua"]={["Path"]="scripts/items/achiyalabopa_bullet_pouch.lua",["SHA256"]="f43d017df6cc1ed060728f4f615be3efc98f04e958a29ca16017c7f812e6cfb4",["Text"]="-----------------------------------\n-- ID: 6207\n-- Al. Bull. Pouch\n-- When used, you will obtain one stack of Achiyalabopa Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ACHIYALABOPA_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/achiyalabopa_quiver.lua"]={["Path"]="scripts/items/achiyalabopa_quiver.lua",["SHA256"]="2b0632475ab5f20f52ef31f0d80b629ba1772695328de2da8cd54e4cd5d584e5",["Text"]="-----------------------------------\n-- ID: 6199\n-- Achiyal. Quiver\n-- When used, you will obtain one stack of Achiyalabopa Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ACHIYALABOPA_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/acid_bolt_quiver.lua"]={["Path"]="scripts/items/acid_bolt_quiver.lua",["SHA256"]="faaa78d8863ce05b99373aa342e1745710ea44c524e3a82bfe1de15ceb3af4fa",["Text"]="-----------------------------------\n-- ID: 5335\n-- Item: Acid Bolt Quiver\n-- When used, you will obtain one stack of Acid Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ACID_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/acorn_cookie.lua"]={["Path"]="scripts/items/acorn_cookie.lua",["SHA256"]="66904414f73270341edcba87047c0b95ddb0e41e7cbf53a28b09e061e85222f0",["Text"]="-----------------------------------\n-- ID: 4510\n-- Item: Acorn Cookie\n-- Food Effect: 3Min, All Races\n-----------------------------------\n-- Aquan killer +10\n-- Silence resistance +10\n-- MP recovered while healing +3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AQUAN_KILLER, 10)\n    effect:addMod(xi.mod.SILENCERES, 10)\n    effect:addMod(xi.mod.MPHEAL, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/acrobats_belt.lua"]={["Path"]="scripts/items/acrobats_belt.lua",["SHA256"]="a0abbd3bcbb707706d9ec2e97710edf2e5294b55ae8f475d2b79f4e623753387",["Text"]="-----------------------------------\n-- ID: 15866\n-- Item: acrobats_belt\n-- Item Effect: AGI +3\n-- Duration: 60 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ACROBATS_BELT) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ACROBATS_BELT)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.ACROBATS_BELT) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 60, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.ACROBATS_BELT })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/adaman_bolt_quiver.lua"]={["Path"]="scripts/items/adaman_bolt_quiver.lua",["SHA256"]="a8ed0ab5edc0b04c07f91bcdb8a0a4ed750322564d10e8fe29cee47dde750e23",["Text"]="-----------------------------------\n-- ID: 5913\n-- Adaman Bolt Quiver\n-- When used, you will obtain one stack of Adaman Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ADAMAN_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/adaman_bullet_pouch.lua"]={["Path"]="scripts/items/adaman_bullet_pouch.lua",["SHA256"]="c4a52c79d85eb2be2b624bb39b13c34319e986f04c751a04d039577ee8b49756",["Text"]="-----------------------------------\n-- ID: 5915\n-- Adaman Bullet Pouch\n-- When used, you will obtain one stack of Adaman Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ADAMAN_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/adlivun_bolt_quiver.lua"]={["Path"]="scripts/items/adlivun_bolt_quiver.lua",["SHA256"]="763fd7941a0759f10ffdcf51973fc08373a1c750f90fad9d572366ee685f4cfc",["Text"]="-----------------------------------\n-- ID: 6204\n-- Item: Ad. Bolt Quiver\n-- When used, you will obtain one stack of Adlivun Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ADLIVUN_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/adlivun_bullet_pouch.lua"]={["Path"]="scripts/items/adlivun_bullet_pouch.lua",["SHA256"]="54f3594958f1f25f9dcc46a3f9f2608ff6df10b274f7aa03b83580709f4bd31f",["Text"]="-----------------------------------\n-- ID: 6208\n-- Ad. Bull. Pouch\n-- When used, you will obtain one stack of Adlivun Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ADLIVUN_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/adlivun_quiver.lua"]={["Path"]="scripts/items/adlivun_quiver.lua",["SHA256"]="dd8218fa99b50866a2b386015c9e3488016e03d45e1654e63b255d6218b6fe75",["Text"]="-----------------------------------\n-- ID: 6200\n-- Adlivun Quiver\n-- When used, you will obtain one stack of Adlivun Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ADLIVUN_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/adloquium_schema.lua"]={["Path"]="scripts/items/adloquium_schema.lua",["SHA256"]="3843e9e9334a11437b25777fdcd276e497b8ee576d5b6aa1fdcfcbc7263ca52c",["Text"]="-----------------------------------\n-- ID: 6061\n-- Item: Adloquium Schema\n-- Teaches the white magic Adloquium\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.ADLOQUIUM)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.ADLOQUIUM)\nend\n\nreturn itemObject\n"},["scripts/items/aero_mufflers.lua"]={["Path"]="scripts/items/aero_mufflers.lua",["SHA256"]="482ad335baa917a4ee9c697c2bbfe2ebca504c4148c1ca494f6058adf1a51088",["Text"]="-----------------------------------\n-- ID: 14989\n-- Aero Mufflers\n-- Enchantment: \"Enaero\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local fakeSpell = GetSpell(xi.magic.spell.ENAERO)\n    xi.spells.enhancing.useEnhancingSpell(target, target, fakeSpell)\nend\n\nreturn itemObject\n"},["scripts/items/agaricus_mushroom.lua"]={["Path"]="scripts/items/agaricus_mushroom.lua",["SHA256"]="ed5431ce408e0ac6873fa46f3133321a314646dbdd95a2d93e48b5e4040ee6d0",["Text"]="-----------------------------------\n-- ID: 5680\n-- Item: agaricus mushroom\n-- Food Effect: 5 Min, All Races\n-----------------------------------\n-- STR -4\n-- MND +2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, -4)\n    effect:addMod(xi.mod.MND, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/aged_box_bayld.lua"]={["Path"]="scripts/items/aged_box_bayld.lua",["SHA256"]="52a8bbc3d28a8fea8a57c2f3edc22d0efac4f6720a4500979fddb4ecdf578a84",["Text"]="-----------------------------------\n-- ID: 6267\n-- Item: Aged Box (Bayld)\n-- When used, you will obtain 3-15 H-P Bayld\n-----------------------------------\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.PINCH_OF_HIGH_PURITY_BAYLD, math.randomInt(3, 15) } })\nend\n\nreturn itemObject\n"},["scripts/items/agility_potion.lua"]={["Path"]="scripts/items/agility_potion.lua",["SHA256"]="f367bebe316743255ae002494e675e3c3d672b5712119a4c96f880025f320428",["Text"]="-----------------------------------\n--  ID: 4205\n--  Item: Agility Potion\n--  Agility 7\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.AGI_BOOST, { power = 7, duration = 180, origin = user })\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 900, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/aileens_delight.lua"]={["Path"]="scripts/items/aileens_delight.lua",["SHA256"]="66cef60e11373b23c2f8e367b53fdcb3e18e53eb23b62dc16eb81ecef2f83529",["Text"]="-----------------------------------\n-- ID: 5674\n-- Item: Aileen's Delight\n-- Food Effect: 60 Min, All Races\n-----------------------------------\n-- HP +50\n-- MP +50\n-- STR +4\n-- DEX +4\n-- VIT +4\n-- AGI +4\n-- INT +4\n-- MND +4\n-- CHR +4\n-- MP recovered while healing +2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 50)\n    effect:addMod(xi.mod.FOOD_MP, 50)\n    effect:addMod(xi.mod.STR, 4)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.AGI, 4)\n    effect:addMod(xi.mod.INT, 4)\n    effect:addMod(xi.mod.MND, 4)\n    effect:addMod(xi.mod.CHR, 4)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/aiming_gloves.lua"]={["Path"]="scripts/items/aiming_gloves.lua",["SHA256"]="e7d41da66f1a7c681beb07932f5ce569f048bebcd6fdf29962d9b66e35a201ad",["Text"]="-----------------------------------\n-- ID: 14957\n-- Item: aiming_gloves\n-- Item Effect: RACC +3\n-- Duration: 60 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.AIMING_GLOVES) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.AIMING_GLOVES)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.AIMING_GLOVES) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 60, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.AIMING_GLOVES })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.RACC, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/air_rider.lua"]={["Path"]="scripts/items/air_rider.lua",["SHA256"]="7d4aae22233d2a784282a35f5e4b88728319063396a6db8fd41d622ad301d4c9",["Text"]="-----------------------------------\n-- ID: 4218\n-- Item: Air Rider\n-- A goblin in a Santa outfit rides a sleigh in a downward spiral\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/air_spirit_pact.lua"]={["Path"]="scripts/items/air_spirit_pact.lua",["SHA256"]="22c6791ac5b805fcd162a0403981eb53ff575eb7d80986b0dc7f24d858108ef9",["Text"]="-----------------------------------\n-- ID: 4898\n-- Air Spirit Pact\n-- Teaches the summoning magic Air Spirit\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.AIR_SPIRIT)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.AIR_SPIRIT)\nend\n\nreturn itemObject\n"},["scripts/items/airborne.lua"]={["Path"]="scripts/items/airborne.lua",["SHA256"]="c820d77bd336a5cf005d574c900427c223f3512d9bf2405e151673e66288e632",["Text"]="-----------------------------------\n-- ID: 4186\n-- Item: Airborne\n-- A goblin with a rainbow colored parasail rides in a downward spiral\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/alabaligi.lua"]={["Path"]="scripts/items/alabaligi.lua",["SHA256"]="ab9fb328283067abd2768b18ca733df9f5418c429eda97244730c14a124f7bd4",["Text"]="-----------------------------------\n-- ID: 5461\n-- Item: Alabaligi\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/alchemists_belt.lua"]={["Path"]="scripts/items/alchemists_belt.lua",["SHA256"]="357b89200cfd61d473b3214b2c4acbf5de381f01d1be0f77d0beae22e8821976",["Text"]="-----------------------------------\n-- ID: 15450\n-- Item: Alchemist's belt\n-- Enchantment: Synthesis image support\n-- Duration: 8Min\n-- Alchemy Skill +3\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.ALCHEMY_IMAGERY) then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.ALCHEMY_IMAGERY, { power = 3, duration = 480, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/algol.lua"]={["Path"]="scripts/items/algol.lua",["SHA256"]="ef86fb3c501ab54d3a706f466dd8d43468dc91766b70fec2adb544edfe623f88",["Text"]="-----------------------------------\n-- ID: 18385\n-- Item: Suzaku's Scythe\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    -- TODO: chance and damage is made up.\n    local pTable =\n    {\n        chance         = 33,\n        basePower      = 33,\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/allied_ring.lua"]={["Path"]="scripts/items/allied_ring.lua",["SHA256"]="c3a80bf0d7f2a9004dcb5c722cacd15b19d32e6e8658ce3341ed23fbd75bfcaa",["Text"]="-----------------------------------\n-- ID: 14671\n-- Item: allied ring\n-- Experience point bonus\n-----------------------------------\n-- Bonus: +150%\n-- Duration: 720 min\n-- Max bonus: 30000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.DEDICATION) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 150\n    local duration  = 43200\n    local subpower  = 30000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/allies_die.lua"]={["Path"]="scripts/items/allies_die.lua",["SHA256"]="f6829209fea1a2f524f15d0724d66282dbfe24a54aff46b5e38f297f3eb0e8e9",["Text"]="-----------------------------------\n-- ID: 5502\n-- Allies' Die\n-- Teaches the job ability Allies Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.ALLIES_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.ALLIES_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/altanas_repast.lua"]={["Path"]="scripts/items/altanas_repast.lua",["SHA256"]="787affbe94fbbacfc1bd52de32d01a44d11b766ef3bd9e7e026d4ba4069f5b30",["Text"]="-----------------------------------\n-- ID: 6538\n-- Item: Altanas Repast\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- AoE:\n-- STR+10\n-- DEX+10\n-- VIT+10\n-- AGI+10\n-- INT+10\n-- MND+10\n-- CHR+10\n-- Accuracy+70\n-- Attack+70\n-- R. Accuracy+70\n-- R. Attack+70\n-- M. Accuracy+70\n-- \"M. Atk. Bonus\"+10\n-- \"M. Def. Bonus\"+3\n-- Evasion+70\n-- DEF+70\n-- M. Evasion+70\n-- \"Store TP\"+6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:forMembersInRange(30, function(member)\n        if not member:hasStatusEffect(xi.effect.FOOD) then\n            member:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\n        end\n    end)\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 10)\n    effect:addMod(xi.mod.DEX, 10)\n    effect:addMod(xi.mod.VIT, 10)\n    effect:addMod(xi.mod.AGI, 10)\n    effect:addMod(xi.mod.INT, 10)\n    effect:addMod(xi.mod.MND, 10)\n    effect:addMod(xi.mod.CHR, 10)\n    effect:addMod(xi.mod.ACC, 70)\n    effect:addMod(xi.mod.ATT, 70)\n    effect:addMod(xi.mod.RACC, 70)\n    effect:addMod(xi.mod.RATT, 70)\n    effect:addMod(xi.mod.MACC, 70)\n    effect:addMod(xi.mod.MATT, 10)\n    effect:addMod(xi.mod.MDEF, 3)\n    effect:addMod(xi.mod.EVA, 70)\n    effect:addMod(xi.mod.DEF, 70)\n    effect:addMod(xi.mod.MEVA, 70)\n    effect:addMod(xi.mod.STORETP, 6)\n    target:addPetMod(xi.mod.STR, 10)\n    target:addPetMod(xi.mod.DEX, 10)\n    target:addPetMod(xi.mod.VIT, 10)\n    target:addPetMod(xi.mod.AGI, 10)\n    target:addPetMod(xi.mod.INT, 10)\n    target:addPetMod(xi.mod.MND, 10)\n    target:addPetMod(xi.mod.CHR, 10)\n    target:addPetMod(xi.mod.ACC, 70)\n    target:addPetMod(xi.mod.ATT, 70)\n    target:addPetMod(xi.mod.RACC, 70)\n    target:addPetMod(xi.mod.RATT, 70)\n    target:addPetMod(xi.mod.MACC, 70)\n    target:addPetMod(xi.mod.MATT, 10)\n    target:addPetMod(xi.mod.MDEF, 3)\n    target:addPetMod(xi.mod.EVA, 70)\n    target:addPetMod(xi.mod.DEF, 70)\n    target:addPetMod(xi.mod.MEVA, 70)\n    target:addPetMod(xi.mod.STORETP, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:delPetMod(xi.mod.STR, 10)\n    target:delPetMod(xi.mod.DEX, 10)\n    target:delPetMod(xi.mod.VIT, 10)\n    target:delPetMod(xi.mod.AGI, 10)\n    target:delPetMod(xi.mod.INT, 10)\n    target:delPetMod(xi.mod.MND, 10)\n    target:delPetMod(xi.mod.CHR, 10)\n    target:delPetMod(xi.mod.ACC, 70)\n    target:delPetMod(xi.mod.ATT, 70)\n    target:delPetMod(xi.mod.RACC, 70)\n    target:delPetMod(xi.mod.RATT, 70)\n    target:delPetMod(xi.mod.MACC, 70)\n    target:delPetMod(xi.mod.MATT, 10)\n    target:delPetMod(xi.mod.MDEF, 3)\n    target:delPetMod(xi.mod.EVA, 70)\n    target:delPetMod(xi.mod.DEF, 70)\n    target:delPetMod(xi.mod.MEVA, 70)\n    target:delPetMod(xi.mod.STORETP, 6)\nend\n\nreturn itemObject\n"},["scripts/items/altanas_repast_+1.lua"]={["Path"]="scripts/items/altanas_repast_+1.lua",["SHA256"]="ae77e14ff36b56b2fc1c1cf7e535a1f8f2da8629e7bc6bf98b26664a3be11cc1",["Text"]="-----------------------------------\n-- ID: 6539\n-- Item: Altanas Repast +1\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- AoE:\n-- STR+15\n-- DEX+15\n-- VIT+15\n-- AGI+15\n-- INT+15\n-- MND+15\n-- CHR+15\n-- Accuracy+80\n-- Attack+80\n-- R. Accuracy+80\n-- R. Attack+80\n-- M. Accuracy+80\n-- \"M. Atk. Bonus\"+15\n-- \"M. Def. Bonus\"+4\n-- Evasion+80\n-- DEF+80\n-- M. Evasion+80\n-- \"Store TP\"+7\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:forMembersInRange(30, function(member)\n        if not member:hasStatusEffect(xi.effect.FOOD) then\n            member:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\n        end\n    end)\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 15)\n    effect:addMod(xi.mod.DEX, 15)\n    effect:addMod(xi.mod.VIT, 15)\n    effect:addMod(xi.mod.AGI, 15)\n    effect:addMod(xi.mod.INT, 15)\n    effect:addMod(xi.mod.MND, 15)\n    effect:addMod(xi.mod.CHR, 15)\n    effect:addMod(xi.mod.ACC, 80)\n    effect:addMod(xi.mod.ATT, 80)\n    effect:addMod(xi.mod.RACC, 80)\n    effect:addMod(xi.mod.RATT, 80)\n    effect:addMod(xi.mod.MACC, 80)\n    effect:addMod(xi.mod.MATT, 15)\n    effect:addMod(xi.mod.MDEF, 4)\n    effect:addMod(xi.mod.EVA, 80)\n    effect:addMod(xi.mod.DEF, 80)\n    effect:addMod(xi.mod.MEVA, 80)\n    effect:addMod(xi.mod.STORETP, 7)\n    target:addPetMod(xi.mod.STR, 15)\n    target:addPetMod(xi.mod.DEX, 15)\n    target:addPetMod(xi.mod.VIT, 15)\n    target:addPetMod(xi.mod.AGI, 15)\n    target:addPetMod(xi.mod.INT, 15)\n    target:addPetMod(xi.mod.MND, 15)\n    target:addPetMod(xi.mod.CHR, 15)\n    target:addPetMod(xi.mod.ACC, 80)\n    target:addPetMod(xi.mod.ATT, 80)\n    target:addPetMod(xi.mod.RACC, 80)\n    target:addPetMod(xi.mod.RATT, 80)\n    target:addPetMod(xi.mod.MACC, 80)\n    target:addPetMod(xi.mod.MATT, 15)\n    target:addPetMod(xi.mod.MDEF, 4)\n    target:addPetMod(xi.mod.EVA, 80)\n    target:addPetMod(xi.mod.DEF, 80)\n    target:addPetMod(xi.mod.MEVA, 80)\n    target:addPetMod(xi.mod.STORETP, 7)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:delPetMod(xi.mod.STR, 15)\n    target:delPetMod(xi.mod.DEX, 15)\n    target:delPetMod(xi.mod.VIT, 15)\n    target:delPetMod(xi.mod.AGI, 15)\n    target:delPetMod(xi.mod.INT, 15)\n    target:delPetMod(xi.mod.MND, 15)\n    target:delPetMod(xi.mod.CHR, 15)\n    target:delPetMod(xi.mod.ACC, 80)\n    target:delPetMod(xi.mod.ATT, 80)\n    target:delPetMod(xi.mod.RACC, 80)\n    target:delPetMod(xi.mod.RATT, 80)\n    target:delPetMod(xi.mod.MACC, 80)\n    target:delPetMod(xi.mod.MATT, 15)\n    target:delPetMod(xi.mod.MDEF, 4)\n    target:delPetMod(xi.mod.EVA, 80)\n    target:delPetMod(xi.mod.DEF, 80)\n    target:delPetMod(xi.mod.MEVA, 80)\n    target:delPetMod(xi.mod.STORETP, 7)\nend\n\nreturn itemObject\n"},["scripts/items/altanas_repast_+2.lua"]={["Path"]="scripts/items/altanas_repast_+2.lua",["SHA256"]="8425e9c322f5b8e983b7165fe89b5c734bc387fc5db0a61ac1edc12281545c8f",["Text"]="-----------------------------------\n-- ID: 6540\n-- Item: Altanas Repast +2\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- AoE:\n-- STR+20\n-- DEX+20\n-- VIT+20\n-- AGI+20\n-- INT+20\n-- MND+20\n-- CHR+20\n-- Accuracy+90\n-- Attack+90\n-- R. Accuracy+90\n-- R. Attack+90\n-- M. Accuracy+90\n-- \"M. Atk. Bonus\"+20\n-- \"M. Def. Bonus\"+5\n-- Evasion+90\n-- DEF+90\n-- M. Evasion+90\n-- \"Store TP\"+8\n-----------------------------------\n---@