mod.STR, 20)\n    target:delPetMod(xi.mod.DEX, 20)\n    target:delPetMod(xi.mod.VIT, 20)\n    target:delPetMod(xi.mod.AGI, 20)\n    target:delPetMod(xi.mod.INT, 20)\n    target:delPetMod(xi.mod.MND, 20)\n    target:delPetMod(xi.mod.CHR, 20)\n    target:delPetMod(xi.mod.ACC, 90)\n    target:delPetMod(xi.mod.ATT, 90)\n    target:delPetMod(xi.mod.RACC, 90)\n    target:delPetMod(xi.mod.RATT, 90)\n    target:delPetMod(xi.mod.MACC, 90)\n    target:delPetMod(xi.mod.MATT, 20)\n    target:delPetMod(xi.mod.MDEF, 5)\n    target:delPetMod(xi.mod.EVA, 90)\n    target:delPetMod(xi.mod.DEF, 90)\n    target:delPetMod(xi.mod.MEVA, 90)\n    target:delPetMod(xi.mod.STORETP, 8)\nend\n\nreturn itemObject\n"},["scripts/items/anchovy_pizza.lua"]={["Path"]="scripts/items/anchovy_pizza.lua",["SHA256"]="56d6fdf363565e3e508500de95c057ff1651135494d57d167b701c4ecba55667",["Text"]="-----------------------------------\n-- ID: 5699\n-- Item: anchovy_pizza\n-- Food Effect: 3 hours, all Races\n-----------------------------------\n-- HP +30\n-- DEX +1\n-- Accuracy +9% (Cap 15)\n-- Attack +10% (Cap 20)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 30)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.FOOD_ACCP, 9)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 15)\n    effect:addMod(xi.mod.FOOD_ATTP, 10)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 20)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/anchovy_pizza_+1.lua"]={["Path"]="scripts/items/anchovy_pizza_+1.lua",["SHA256"]="76849ec11cf23de7a1aa403a8fe14f2f7ea49385ef0aad2bf30c446ffafcc42a",["Text"]="-----------------------------------\n-- ID: 5700\n-- Item: anchovy_pizza_+1\n-- Food Effect: 4 hours, all Races\n-----------------------------------\n-- HP +35\n-- DEX +2\n-- Accuracy +9% (Cap 16)\n-- Attack +10% (Cap 21)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 35)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.FOOD_ACCP, 9)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 16)\n    effect:addMod(xi.mod.FOOD_ATTP, 10)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 21)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/anemohelix_schema.lua"]={["Path"]="scripts/items/anemohelix_schema.lua",["SHA256"]="96276eca10ea6de77f011e308af7a184665e52f63d36454f5eec6b53d5795de5",["Text"]="-----------------------------------\n-- ID: 6046\n-- Item: Anemohelix Schema\n-- Teaches the black magic Anemohelix\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.ANEMOHELIX)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.ANEMOHELIX)\nend\n\nreturn itemObject\n"},["scripts/items/angelwing.lua"]={["Path"]="scripts/items/angelwing.lua",["SHA256"]="85a4babe7d8313c6b97ad953011efdb67e7d464efc69d01ad673a8070623d555",["Text"]="-----------------------------------\n-- ID: 5441\n-- Item: Angelwing\n-- Adds angel wings to the user\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/angler_stewpot.lua"]={["Path"]="scripts/items/angler_stewpot.lua",["SHA256"]="ef63243687ebf31dd2994aa89364edaad1a9d0e864e4e3ebe87f8e7b9eec7068",["Text"]="-----------------------------------\n-- ID: 5611\n-- Item: Angler's Stewpot\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP +10% (cap 200)\n-- MP +10\n-- HP Recoverd while healing 5\n-- MP Recovered while healing 1\n-- Accuracy +15% Cap 15\n-- Ranged Accuracy 15% Cap 15\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 10)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 200)\n    effect:addMod(xi.mod.FOOD_MP, 10)\n    effect:addMod(xi.mod.HPHEAL, 5)\n    effect:addMod(xi.mod.MPHEAL, 1)\n    effect:addMod(xi.mod.FOOD_ACCP, 15)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 15)\n    effect:addMod(xi.mod.FOOD_RACCP, 15)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 15)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/anglers_cassoulet.lua"]={["Path"]="scripts/items/anglers_cassoulet.lua",["SHA256"]="6ced9aeb48504663c172933473addbfb6f86152fd7aca4e2f39af300f8ed7076",["Text"]="-----------------------------------\n-- ID: 5704\n-- Item: anglers_cassoulet\n-- Food Effect: 30, All Races\n-----------------------------------\n-- VIT -1\n-- AGI +5\n-- Ranged Accuracy +1\n-- Regen +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.REGEN, 1)\n    effect:addMod(xi.mod.VIT, -1)\n    effect:addMod(xi.mod.AGI, 5)\n    effect:addMod(xi.mod.RACC, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/animus_augeo_schema.lua"]={["Path"]="scripts/items/animus_augeo_schema.lua",["SHA256"]="f245521dbce5b6db541aeb9be06170db376e9e8798f0404fba7f03f12b10412f",["Text"]="-----------------------------------\n-- ID: 6059\n-- Item: Animus Augeo Schema\n-- Teaches the white magic Animus Augeo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.ANIMUS_AUGEO)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.ANIMUS_AUGEO)\nend\n\nreturn itemObject\n"},["scripts/items/animus_minuo_schema.lua"]={["Path"]="scripts/items/animus_minuo_schema.lua",["SHA256"]="9b61c22b4670760d8c0d76b427e069db92faae3de7dc131846b0f2a148a10061",["Text"]="-----------------------------------\n-- ID: 6060\n-- Item: Animus Minuo Schema\n-- Teaches the white magic Animus Minuo\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.ANIMUS_MINUO)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.ANIMUS_MINUO)\nend\n\nreturn itemObject\n"},["scripts/items/anniversary_ring.lua"]={["Path"]="scripts/items/anniversary_ring.lua",["SHA256"]="df2b8b6525619e5ee94e68998c56e95383f1577f74c0d3e5e18a0c2ed50247c5",["Text"]="-----------------------------------\n-- ID: 15793\n-- Item: Anniversary Ring\n-- Experience point bonus\n-----------------------------------\n-- Bonus: +100%\n-- Duration: 720 min\n-- Max bonus: 10000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.DEDICATION) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 100\n    local duration  = 43200\n    local subpower  = 10000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/anthos_xiphos.lua"]={["Path"]="scripts/items/anthos_xiphos.lua",["SHA256"]="9c72219e7c4c9cb1e21bd909d59adac290364ce91f358898c5af146d5d175e1f",["Text"]="-----------------------------------\n-- ID: 17750\n-- Item: Anthos Xiphos\n-- Additional effect: water damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 10 + utils.clamp(dStat * 0.0926, 0, 25), -- 0-5% over 54 dINT, approx.\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WATER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/antidote.lua"]={["Path"]="scripts/items/antidote.lua",["SHA256"]="7642151d5dcbf1fa2a24e6990e25bc10f109a539499c05d36409157f62084f51",["Text"]="-----------------------------------\n-- ID: 4148\n-- Item: Antidote\n-- Item Effect: This potion remedies poison.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    if target:hasStatusEffect(xi.effect.POISON) then\n        target:delStatusEffect(xi.effect.POISON)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/antlion_quiver.lua"]={["Path"]="scripts/items/antlion_quiver.lua",["SHA256"]="1660b3568587234c4ec2615b592fca32ef039cc5578716b1967f85d5f589cfbc",["Text"]="-----------------------------------\n-- ID: 5819\n-- Item: Antlion Quiver\n-- When used, you will obtain one stack of Antlion Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ANTLION_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/anubiss_knife.lua"]={["Path"]="scripts/items/anubiss_knife.lua",["SHA256"]="54d00b9bc1d2dc588325321fa21ecc73f10ae35a5fb17bdff020e1857cc2f954",["Text"]="-----------------------------------\n-- ID: 17624\n-- Item: anubiss_knife\n-- Item Effect: Poison 1HP / Removes 60 HP over 180 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.POISON) then\n        target:addStatusEffect(xi.effect.POISON, { power = 1, duration = 180, origin = user, tick = 3 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/apingaut_snow_cone.lua"]={["Path"]="scripts/items/apingaut_snow_cone.lua",["SHA256"]="1104665be88812996029d20629bd8768754efaf1c2a5db3ae4bf9932d4eebbf4",["Text"]="-----------------------------------\n-- ID: 6224\n-- Item: Apingaut snow cone\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- MP +25% (cap 105)\n-- INT +6\n-- MND +6\n-- Magic Atk. Bonus +14\n-- Lizard Killer +6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 25)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 105)\n    effect:addMod(xi.mod.INT, 6)\n    effect:addMod(xi.mod.MND, 6)\n    effect:addMod(xi.mod.MATT, 14)\n    effect:addMod(xi.mod.LIZARD_KILLER, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/apkallu_egg.lua"]={["Path"]="scripts/items/apkallu_egg.lua",["SHA256"]="0fee4a70632c47ec1f3bd45e82a8c7ee43c95d3f7d887f9ab213a7a299bcc879",["Text"]="-----------------------------------\n-- ID: 5568\n-- Item: Apkallu Egg\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Health 6\n-- Magic 6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 6)\n    effect:addMod(xi.mod.FOOD_MP, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/apollos_staff.lua"]={["Path"]="scripts/items/apollos_staff.lua",["SHA256"]="8a2a1585aada59805eaef10b4d6730f6848203559d5ba0d8769bc5842a525c14",["Text"]="-----------------------------------\n-- ID: 17558\n-- Item: Apollo's Staff\n-- Additional effect: light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 25, -- guessed\n        basePower      = math.randomInt(25, 34),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/apple_au_lait_tank.lua"]={["Path"]="scripts/items/apple_au_lait_tank.lua",["SHA256"]="71a62afec8518d8a118a05bcfb7323b9113e3895fd9624c12efd02db9fd712d7",["Text"]="-----------------------------------\n--  ID: 16224\n--  Apple au lait Tank\n--  When used, you will obtain one Apple au lait\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.FLASK_OF_APPLE_AU_LAIT, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/apple_pie.lua"]={["Path"]="scripts/items/apple_pie.lua",["SHA256"]="bfa717a93fc00e99f7b5e7b5714079027703f976045460505412e50a6125d8b8",["Text"]="-----------------------------------\n-- ID: 4413\n-- Item: Apple Pie\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Magic 25\n-- Agility -1\n-- Intelligence 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 25)\n    effect:addMod(xi.mod.AGI, -1)\n    effect:addMod(xi.mod.INT, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/apple_pie_+1.lua"]={["Path"]="scripts/items/apple_pie_+1.lua",["SHA256"]="2382d119784c0c40dd0356d81f708c7bdd047162bba10ec35fcdf1eb4e7b6f0d",["Text"]="-----------------------------------\n-- ID: 4320\n-- Item: Apple Pie +1\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Magic 30\n-- Intelligence 4\n-- Magic Regen While Healing 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 30)\n    effect:addMod(xi.mod.INT, 4)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/aquilos_staff.lua"]={["Path"]="scripts/items/aquilos_staff.lua",["SHA256"]="cc34f8186f384c641a57102f887ef5f7b512e114da3475a9d2bce8380f7d005c",["Text"]="-----------------------------------\n-- ID: 17548\n-- Item: Aquilo's Staff\n-- Additional effect: ice damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 25, -- guessed\n        basePower      = math.randomInt(25, 34),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.ICE,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/aries_mantle.lua"]={["Path"]="scripts/items/aries_mantle.lua",["SHA256"]="458042ccf98f9a748aa0eb5f55dcf855b2a1d424c667a388bda008e25de8c78c",["Text"]="-----------------------------------\n-- ID: 13693\n-- Item: Aries Mantle\n-- Enchantment: Sleep\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if\n        target:hasStatusEffect(xi.effect.SLEEP_I) or\n        target:hasStatusEffect(xi.effect.SLEEP_II) or\n        target:hasStatusEffect(xi.effect.LULLABY)\n    then\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    else\n        target:addStatusEffect(xi.effect.SLEEP_I, { duration = 30, origin = user })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/armageddon.lua"]={["Path"]="scripts/items/armageddon.lua",["SHA256"]="b9092da20751a87832c04bce0721e4d51ab3d1cc30586bbbca3334ae72809e54",["Text"]="-----------------------------------\n-- ID: 19469\n-- Item: Armageddon\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getFreeSlotsCount() == 0 then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DEVASTATING_BULLET, 99 } }) -- Devastating Bullet x99\nend\n\nreturn itemObject\n"},["scripts/items/armored_ring.lua"]={["Path"]="scripts/items/armored_ring.lua",["SHA256"]="442664cc8a4eaf15a02e989e819e8f85160d4accaac4c7888517376e7794ca07",["Text"]="-----------------------------------\n-- ID: 15783\n-- Item: Armored Ring\n-- Item Effect: Defence +8\n-- Duration 30 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ARMORED_RING) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.ARMORED_RING)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.ARMORED_RING) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.ARMORED_RING })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEF, 8)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/army_biscuit.lua"]={["Path"]="scripts/items/army_biscuit.lua",["SHA256"]="d7e7a43aa4336f98dd27594ee8ad66b361a96359dc6aa6a619cab9ea4a329661",["Text"]="-----------------------------------\n-- ID: 5657\n-- Item: army_biscuit\n-- Food Effect: 5Min?, All Races\n-----------------------------------\n-- HP Recovered While Healing 3\n-- MP Recovered While Healing 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HPHEAL, 3)\n    effect:addMod(xi.mod.MPHEAL, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/arondight.lua"]={["Path"]="scripts/items/arondight.lua",["SHA256"]="53746c17bae3b9be3c6de06356f1284a8ad401a2ac79d11cf4e3ce9d5060ce4d",["Text"]="-----------------------------------\n-- ID: 16945\n-- Item: Arondight\n-- Additional effect: water damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.CHR) - target:getStat(xi.mod.CHR)\n    local power  = 13 + utils.clamp(dStat, 0, 60)\n    local pTable =\n    {\n        chance         = 1 + utils.clamp(dStat * 0.908, 1, 50), -- Averaged over the whole range\n        basePower      = math.randomInt(power, power + 7),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WATER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/ascalon.lua"]={["Path"]="scripts/items/ascalon.lua",["SHA256"]="1dc43aa02b03a7a045e5be00743c60dfe447ca1d9f48e7636f9bdef7a8aedb88",["Text"]="-----------------------------------\n-- ID: 16943\n-- Item: Ascalon\n-- Additional effect: light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    -- TODO: does Dragon Affinity cover this?\n    if not target:isMob() and target:getEcosystem() ~= xi.ecosystem.DRAGON then\n        return 0, 0, 0\n    end\n\n    -- This is really wrong. It's based off Arondight (a similar sword) which appears to have two knees?\n    -- Needs testing.\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 100,\n        basePower      = 13 + utils.clamp(dStat * 0.9, 0, 84), -- Averaged over the whole range\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"}};
